WITH filtered AS (SELECT id, supplier_name, country, city, CONCAT(city, '/', supplier_name) AS city_supplier_name, COALESCE(city, 'UNKNOWN') AS city_filled FROM suppliers WHERE city IS NOT NULL), cleaned AS (SELECT id, country, city_filled, SUBSTRING(country, 1, 3) AS country_prefix FROM filtered WHERE city IS NOT NULL), kept AS (SELECT s.* FROM cleaned s WHERE EXISTS (SELECT 1 FROM products ch WHERE ch.supplier_id = s.id AND ch.price > 390)), not_flagged AS (SELECT s.* FROM kept s WHERE EXISTS (SELECT 1 FROM products ch WHERE ch.supplier_id = s.id AND ch.brand = 'Initech')), grouped AS (SELECT country, SIZE(COLLECT_SET(country)) AS num_countries, COUNT(CASE WHEN country = 'TH' THEN 1 END) AS th_count, COUNT(DISTINCT id) AS distinct_ids FROM not_flagged GROUP BY country) SELECT country, th_count FROM grouped ORDER BY country DESC, th_count DESC
